pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount1 = bound(amount1, 1, 10 ether);
        amount2 = bound(amount2, 1, 10 ether);
        vm.deal(actor, amount1 + amount2);

        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        (, uint256 bal) = c.Acc(actor);
        assertEq(bal, amount1 + amount2);
    }
}
